.cidade {
  --vidro: rgba(255, 255, 255, 0.84);
  --vidro-borda: rgba(255, 255, 255, 0.9);
  --texto: #0F172A;
  --texto-2: #475569;
  --texto-3: #94A3B8;
  --linha: #E2E8F0;
  --sobe: #059669;
  --desce: #DC2626;
  --sombra: 0 8px 24px rgba(30, 27, 75, 0.14), 0 2px 6px rgba(30, 27, 75, 0.08);
  --rodape: 0px;
  position: absolute;
  inset: 0;
  overflow: hidden;
  border-radius: 14px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  color: var(--texto);
  background: radial-gradient(60% 55% at 85% 0%, #E9D5FF 0%, transparent 70%), linear-gradient(180deg, #FDE2E4 0%, #DBEAFE 100%);
  transition: background 0.8s;
  user-select: none;
}
.cidade.noite {
  --vidro: rgba(15, 23, 42, 0.84);
  --vidro-borda: rgba(148, 163, 184, 0.22);
  --texto: #F1F5F9;
  --texto-2: #CBD5E1;
  --texto-3: #64748B;
  --linha: #1E293B;
  --sobe: #34D399;
  --desce: #F87171;
  --sombra: 0 8px 24px rgba(0, 0, 0, 0.45);
  background: radial-gradient(60% 55% at 85% 0%, #312E81 0%, transparent 70%), linear-gradient(180deg, #0B1026 0%, #111827 100%);
}
.cidade.com-letreiro {
  --rodape: 34px;
}
.cidade.sobre-predio canvas {
  cursor: pointer;
}
.cidade button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}
.cidade-palco {
  position: absolute;
  inset: 0;
}
.cidade-palco canvas {
  display: block;
  outline: none;
}
.cidade-chip,
.cidade-passaporte,
.cidade-doca,
.cidade-painel,
.cidade-zoom .cidade-botao {
  background: var(--vidro);
  backdrop-filter: blur(12px) saturate(1.3);
  border: 1px solid var(--vidro-borda);
  box-shadow: var(--sombra);
}
.cidade .cidade-botao {
  width: 32px;
  height: 32px;
  flex: none;
  border-radius: 10px;
  display: grid;
  place-items: center;
  border: 1px solid var(--linha);
  background: transparent;
  font-size: 15px;
  line-height: 1;
  padding: 0;
  transition: transform 0.15s;
}
.cidade .cidade-botao:hover {
  transform: translateY(-1px);
}
.cidade-chip {
  position: absolute;
  top: 10px;
  left: 10px;
  z-index: 5;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 6px 6px 6px 8px;
  border-radius: 14px;
}
.cidade-chip strong {
  display: block;
  font-size: 13px;
  font-weight: 700;
}
.cidade-chip span {
  display: block;
  font-size: 10.5px;
  color: var(--texto-2);
}
.cidade-chip-logo {
  width: 30px;
  height: 30px;
  border-radius: 9px;
  display: grid !important;
  place-items: center;
  font-size: 16px !important;
  background: linear-gradient(135deg, #6366F1, #EC4899);
}
.cidade-etiquetas {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
}
.cidade .etiqueta {
  position: absolute;
  left: 0;
  top: 0;
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 3px 9px 3px 3px;
  border-radius: 999px;
  border: 0;
  background: rgba(255, 255, 255, 0.95);
  color: #0F172A !important;
  font-size: 11.5px;
  font-weight: 600;
  white-space: nowrap;
  box-shadow: 0 4px 12px rgba(15, 23, 42, 0.18);
  pointer-events: auto;
  transition: opacity 0.25s, box-shadow 0.2s;
}
.cidade .etiqueta::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -4px;
  width: 9px;
  height: 9px;
  background: inherit;
  transform: translateX(-50%) rotate(45deg);
  border-radius: 2px;
  z-index: -1;
}
.cidade .etiqueta i {
  font-style: normal;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--cor);
  font-size: 11px;
}
.cidade .etiqueta .etiqueta-valor {
  font-weight: 800;
  padding: 1px 6px;
  border-radius: 999px;
  background: #EEF2FF;
  color: #3730A3;
  font-size: 11px;
}
.cidade .etiqueta .etiqueta-valor:empty {
  display: none;
}
.cidade .etiqueta.bom .etiqueta-valor {
  background: #DCFCE7;
  color: #166534;
}
.cidade .etiqueta.ruim .etiqueta-valor {
  background: #FEE2E2;
  color: #B91C1C;
}
.cidade .etiqueta .ok {
  color: #059669;
  font-size: 10px;
  display: none;
}
.cidade .etiqueta.visitado .ok {
  display: inline;
}
.cidade .etiqueta.ativa,
.cidade .etiqueta:hover {
  box-shadow: 0 0 0 3px var(--cor), 0 6px 16px rgba(15, 23, 42, 0.25);
}
.cidade .etiqueta.oculta {
  opacity: 0;
  pointer-events: none;
}
.cidade-passaporte {
  position: absolute;
  left: 10px;
  bottom: calc(var(--rodape) + 10px);
  width: 200px;
  padding: 8px 10px;
  border-radius: 14px;
  z-index: 4;
}
.passaporte-topo {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  font-weight: 700;
  margin-bottom: 6px;
}
.passaporte-topo b {
  color: #6366F1;
}
.passaporte-selos {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 3px;
}
.cidade .selo {
  aspect-ratio: 1;
  border-radius: 7px;
  display: grid;
  place-items: center;
  font-size: 12px;
  background: var(--linha);
  filter: grayscale(1);
  opacity: 0.45;
  border: 0;
  padding: 0;
  transition: filter 0.3s, opacity 0.3s;
}
.cidade .selo.visitado {
  filter: none;
  opacity: 1;
  background: var(--cor);
  animation: carimbo 0.5s cubic-bezier(0.2, 1.6, 0.4, 1);
}
@keyframes carimbo {
  from {
    transform: scale(1.6) rotate(-14deg);
  }
}
.cidade-doca {
  position: absolute;
  left: 50%;
  bottom: calc(var(--rodape) + 10px);
  transform: translateX(-50%);
  display: flex;
  gap: 2px;
  padding: 5px;
  border-radius: 16px;
  z-index: 4;
  max-width: calc(100% - 20px);
  overflow-x: auto;
  scrollbar-width: none;
}
.cidade-doca button {
  border: 0;
  background: transparent;
  border-radius: 11px;
  padding: 4px 8px 3px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  min-width: 58px;
  font-size: 10px;
  font-weight: 600;
  color: var(--texto-2);
  transition: background 0.2s, color 0.2s;
}
.cidade-doca button span {
  font-size: 17px;
  line-height: 1.15;
  transition: transform 0.2s;
}
.cidade-doca button:hover span {
  transform: translateY(-3px) scale(1.12);
}
.cidade-doca button.ativa {
  background: var(--cor);
  color: #FFFFFF;
}
.painel-aberto:not(.estreito) .cidade-doca {
  left: calc(50% - 170px);
}
.cidade-zoom {
  position: absolute;
  right: 10px;
  bottom: calc(var(--rodape) + 10px);
  display: flex;
  flex-direction: column;
  gap: 5px;
  z-index: 4;
  transition: right 0.45s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.cidade-zoom .cidade-botao {
  font-weight: 700;
}
.painel-aberto:not(.estreito) .cidade-zoom {
  right: 352px;
}
.cidade-letreiro {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 34px;
  z-index: 4;
  display: flex;
  align-items: center;
  background: #1E1B4B;
  color: #E0E7FF;
  font-size: 12px;
}
.ao-vivo {
  flex: none;
  height: 100%;
  display: flex;
  align-items: center;
  padding: 0 12px;
  background: linear-gradient(90deg, #E11D48, #EC4899);
  color: #FFF;
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.08em;
}
.letreiro-trilho {
  overflow: hidden;
  flex: 1;
  mask-image: linear-gradient(90deg, transparent, #000 4%, #000 96%, transparent);
}
.letreiro-texto {
  display: inline-flex;
  white-space: nowrap;
  animation: rolar 60s linear infinite;
}
.letreiro-texto span {
  padding: 0 24px;
}
.letreiro-texto b {
  color: #FDE68A;
  font-weight: 700;
}
@keyframes rolar {
  to {
    transform: translateX(-50%);
  }
}
.cidade-letreiro:hover .letreiro-texto {
  animation-play-state: paused;
}
.cidade-painel {
  position: absolute;
  top: 10px;
  right: 10px;
  bottom: calc(var(--rodape) + 10px);
  width: 330px;
  border-radius: 18px;
  z-index: 6;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transform: translateX(calc(100% + 24px));
  visibility: hidden;
  transition: transform 0.45s cubic-bezier(0.2, 0.8, 0.2, 1), visibility 0s 0.45s;
}
.painel-aberto .cidade-painel {
  transform: none;
  visibility: visible;
  transition: transform 0.45s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.estreito .cidade-painel {
  top: auto;
  left: 8px;
  right: 8px;
  width: auto;
  height: 60%;
  transform: translateY(calc(100% + 40px));
}
.estreito.painel-aberto .cidade-painel {
  transform: none;
}
.painel-cabeca {
  position: relative;
  padding: 13px 14px 12px;
  color: #FFF;
  background: radial-gradient(90% 120% at 100% 0%, rgba(255, 255, 255, 0.28), transparent 60%), linear-gradient(135deg, var(--cor), var(--cor-2));
}
.painel-cabeca .linha1 {
  display: flex;
  align-items: center;
  gap: 10px;
}
.painel-icone {
  width: 40px;
  height: 40px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  font-size: 21px;
  background: rgba(255, 255, 255, 0.22);
  border: 1px solid rgba(255, 255, 255, 0.35);
}
.painel-area {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  opacity: 0.85;
}
.painel-nome {
  font-size: 18px;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.cidade .painel-fechar {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.4);
  background: rgba(255, 255, 255, 0.15);
  color: #FFF !important;
  font-size: 14px;
}
.painel-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 10px;
  font-size: 11px;
  font-weight: 600;
}
.painel-nav button {
  border: 1px solid rgba(255, 255, 255, 0.45);
  background: rgba(255, 255, 255, 0.14);
  color: #FFF !important;
  border-radius: 999px;
  padding: 3px 11px;
  font-size: 11px;
  font-weight: 600;
}
.painel-nav button:hover {
  background: rgba(255, 255, 255, 0.28);
}
.painel-corpo {
  padding: 12px 14px 14px;
  overflow-y: auto;
  flex: 1;
  scrollbar-width: thin;
}
.pergunta {
  margin: 0 0 10px;
  font-size: 12px;
  color: var(--texto-2);
}
.pergunta b {
  color: var(--texto);
}
.kpis {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  margin-bottom: 12px;
}
.kpi {
  border: 1px solid var(--linha);
  border-radius: 12px;
  padding: 8px 9px 7px;
  position: relative;
  overflow: hidden;
  animation: subir 0.5s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.kpi small {
  display: block;
  font-size: 10px;
  color: var(--texto-2);
  font-weight: 600;
  padding-right: 50px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.kpi b {
  display: block;
  font-size: 18px;
  font-weight: 700;
  letter-spacing: -0.01em;
  margin: 3px 0 1px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.kpi span {
  display: block;
  font-size: 10px;
  font-weight: 600;
  color: var(--texto-3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.kpi span.sobe {
  color: var(--sobe);
}
.kpi span.desce {
  color: var(--desce);
}
.kpi svg {
  position: absolute;
  right: 7px;
  top: 8px;
  width: 46px;
  height: 18px;
  overflow: visible;
}
.insight {
  border-radius: 13px;
  padding: 11px 13px;
  color: #CBD5E1;
  font-size: 11.5px;
  line-height: 1.45;
  background: radial-gradient(120% 100% at 100% 0%, rgba(34, 211, 238, 0.18), transparent 60%), #0F1E3D;
  border: 1px solid #1E3A8A;
  animation: subir 0.5s 0.15s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.insight small {
  display: block;
  color: #22D3EE;
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: 0.12em;
}
.insight strong {
  display: block;
  color: #FFF;
  font-size: 13px;
  margin: 2px 0 4px;
  line-height: 1.25;
}
@keyframes subir {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}
.cidade-vazio {
  position: absolute;
  left: 50%;
  top: 70px;
  transform: translateX(-50%);
  z-index: 7;
  max-width: 80%;
  padding: 10px 16px;
  border-radius: 12px;
  background: var(--vidro);
  box-shadow: var(--sombra);
  font-size: 12px;
  color: var(--texto-2);
  text-align: center;
}
@media (prefers-reduced-motion: reduce) {
  .cidade * {
    animation: none !important;
    transition: none !important;
  }
}
